const text = (value) => String(value ?? '').trim();
const active = (value) => value === true || ['true', 'yes', '1'].includes(text(value).toLowerCase());
const httpsUrl = (value, label) => {
  const url = text(value);
  if (!/^https:\/\/[^\s?#]+(?:\/[^\s?#]*)?$/i.test(url)) throw new Error(label + ' must be a direct HTTPS URL without a query or fragment.');
  return url;
};
const rows = $input.all().map(item => item.json).filter(row => active(row.Active));
if (!rows.length) throw new Error('The Doctor Profiles tab has no active rows.');
const pilot = rows.filter(row => text(row['Location Code']).toUpperCase() === 'TEST-1');
if (pilot.length !== 1) throw new Error('Exactly one active TEST-1 doctor profile is required for the pilot.');
const row = pilot[0];
const email = text(row['Work Email']).toLowerCase();
if (email !== 'jdold@apexdp.com') throw new Error('The pilot sync is restricted to the TEST-1 recipient.');
const doctorName = text(row['Doctor Name']);
const shortBio = text(row['Short Bio']);
if (!doctorName || !shortBio) throw new Error('Doctor Name and Short Bio are required.');
const verifiedAt = text(row['Verified At']);
if (!verifiedAt) throw new Error('Verified At is required.');
return [{ json: {
  work_email: email, doctor_name: doctorName, credentials: text(row.Credentials), location_code: 'TEST-1',
  profile_url: httpsUrl(row['Profile URL'], 'Profile URL'), photo_url: httpsUrl(row['Photo Source URL'], 'Photo Source URL'),
  short_bio: shortBio, source: text(row.Source), verified_at: verifiedAt, active: true
} }];
